    "created_at" TEXT NOT NULL,
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "country_code" TEXT NOT NULL,
    CONSTRAINT "Customer_pkey" PRIMARY KEY ("id"),
    -- NOT ENFORCED HERE, enforce in the application: is_uuid (from Uuid): regex_full_match(value, "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")
    --   SQLite has no regular expressions unless an extension is loaded
    -- max_length (from ShortText): must be 80 characters or fewer
    CONSTRAINT "Customer_name_max_length" CHECK (length("name") <= 80),
    -- non_blank (from ShortText): must not be blank
    CONSTRAINT "Customer_name_non_blank" CHECK ((length("name") > 0) AND ("name" = trim("name", char(9, 10, 11, 12, 13, 28, 29, 30, 31, 32, 133, 160, 5760, 8192, 8193, 8194, 8195, 8196, 8197, 8198, 8199, 8200, 8201, 8202, 8232, 8233, 8239, 8287, 12288))))
