    --   SQLite has no regular expressions unless an extension is loaded
);
CREATE INDEX "Customer_name_idx" ON "Customer" ("name");
-- Default order, for queries: name ascending.
-- Enforced by the application (not deterministic): in_past: created_at < current() — must be in the past

