    -- NOT ENFORCED HERE, enforce in the application: is_uuid (from Uuid): regex_full_match(value, "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}")
